from lc import L, w, gr, q

B2 = [
 L("One Plant, Many Teas", "同一種植物，很多種茶", [
   "After water, tea is the most widely consumed drink in the world. According to Chinese legend, it was discovered thousands of years ago when tea leaves blew into a pot of boiling water.",
   "What surprises many people is that green, black and oolong tea all come from the same plant, Camellia sinensis. The difference lies in how the leaves are processed. Green tea is heated quickly to prevent oxidation, black tea is fully oxidized, and oolong sits somewhere in between.",
   "Taiwan is especially famous for its oolong, much of it grown in cool mountain areas such as Alishan. The island also gave the world bubble tea, invented in the 1980s, which has since spread to cafés across the globe."],
  [w("consume","verb","/kənˈsuːm/","消耗、飲用","to eat, drink or use something","We consume too much sugar.","widely consumed 被廣泛飲用。"),
   w("legend","noun","/ˈledʒ.ənd/","傳說","an old story that may not be true","According to legend…","According to Chinese legend 根據中國傳說。"),
   w("process","verb","/ˈprɑː.ses/","加工","to treat raw material in a series of steps","processed food","how the leaves are processed 葉子如何加工（被動）。"),
   w("prevent","verb","/prɪˈvent/","防止","to stop something from happening","prevent accidents","prevent + 名詞／prevent A from V-ing。"),
   w("oxidation","noun","/ˌɑːk.səˈdeɪ.ʃən/","氧化","a chemical change when something reacts with oxygen","Oxidation turns apples brown.","動詞 oxidize。"),
   w("in between","phrase","/ɪn bɪˈtwiːn/","介於兩者之間","in the middle of two things","somewhere in between","sits somewhere in between 介於中間。"),
   w("invent","verb","/ɪnˈvent/","發明","to create something new","Who invented the phone?","invented in the 1980s 在 1980 年代被發明。")],
  [gr("After water, 最高級","除了水以外最…。","After water, tea is the most widely consumed drink in the world."),
   gr("What 名詞子句當主詞","What surprises many people = 讓很多人驚訝的事。","What surprises many people is that green, black and oolong tea all come from the same plant"),
   gr("lie in","在於…。","The difference lies in how the leaves are processed.")],
  [q("What do green, black and oolong tea have in common?","They come from the same plant","They are all from Japan","They are all fully oxidized"),
   q("How is green tea different from black tea?","It is heated quickly to prevent oxidation","It is fully oxidized","It uses different water"),
   q("What did Taiwan give the world in the 1980s?","Bubble tea","Black tea","Green tea")]),
 L("Are Electric Cars Really Cleaner?", "電動車真的比較乾淨嗎？", [
   "Electric cars run on batteries instead of petrol, so they produce no exhaust fumes while driving. This makes city air cleaner and streets quieter. In recent years their sales have grown quickly, and they now make up a significant share of new cars sold around the world.",
   "However, an electric car is only as clean as the electricity that charges it. If the power comes from coal, the benefits are smaller. Building the batteries also requires a lot of energy and minerals such as lithium.",
   "Even so, most studies find that over their whole lifetime, electric cars produce fewer emissions than petrol cars. Some drivers still worry about range, meaning how far they can travel on one charge, but better batteries and more charging stations are steadily reducing that concern."],
  [w("battery","noun","/ˈbæt̬.ɚ.i/","電池","a device that stores electricity","My phone battery is low.","複數 batteries。"),
   w("significant","adjective","/sɪɡˈnɪf.ə.kənt/","相當大的、重要的","large or important enough to notice","a significant change","a significant share 相當大的比例。"),
   w("charge","verb","/tʃɑːrdʒ/","充電","to put electricity into a battery","charge your phone","the electricity that charges it 為它充電的電。"),
   w("mineral","noun","/ˈmɪn.ɚ.əl/","礦物","a natural substance found in the ground","minerals such as iron","minerals such as lithium 像鋰這類礦物。"),
   w("lifetime","noun","/ˈlaɪf.taɪm/","一生、使用壽命","the time something exists or is used","over its lifetime","over their whole lifetime 整個使用期間。"),
   w("emission","noun","/iˈmɪʃ.ən/","排放（物）","gas sent out into the air","carbon emissions","常用複數 emissions。"),
   w("range","noun","/reɪndʒ/","續航距離","how far a vehicle can travel","a range of 400 km","range 指電動車一次充電可跑的距離。")],
  [gr("instead of","而不是、代替。","Electric cars run on batteries instead of petrol"),
   gr("only as… as…","只和…一樣…（強調限制）。","an electric car is only as clean as the electricity that charges it"),
   gr("meaning 補充解釋","分詞 meaning 說明前面字的意思。","range, meaning how far they can travel on one charge")],
  [q("Why are electric cars good for city air?","They produce no exhaust while driving","They use coal","They drive slower"),
   q("When are the benefits of an electric car smaller?","When the electricity comes from coal","When it is sunny","When the car is new"),
   q("What does 'range' mean in the text?","How far a car can go on one charge","The price of a car","The size of the battery")]),
 L("Why Volunteering Helps You Too", "為什麼當志工也幫助自己", [
   "Volunteers give their time to help others without being paid. They might tutor children, clean up beaches, help at animal shelters or support people after natural disasters.",
   "While the main goal is to help the community, research suggests volunteers benefit as well. Many report feeling happier and less lonely, and some describe a warm feeling known as the \"helper's high\". Volunteering can also be a good way to learn new skills and meet people with similar interests.",
   "To make a real difference, it helps to choose a cause you care about and an organization you trust. Even a few hours a month, if they are regular, can matter more than a single big effort."],
  [w("volunteer","noun","/ˌvɑː.lənˈtɪr/","志工","a person who works without pay to help others","She is a hospital volunteer.","也可當動詞：volunteer to + V。"),
   w("tutor","verb","/ˈtuː.t̬ɚ/","家教、個別指導","to teach one person or a small group","He tutors students in math.","tutor + 人。"),
   w("shelter","noun","/ˈʃel.tɚ/","收容所","a place that protects people or animals","an animal shelter","animal shelters 動物收容所。"),
   w("community","noun","/kəˈmjuː.nə.t̬i/","社區","the people living in one area","the local community","help the community 幫助社區。"),
   w("lonely","adjective","/ˈloʊn.li/","寂寞的","unhappy because you are alone","She felt lonely.","less lonely 比較不寂寞。"),
   w("cause","noun","/kɑːz/","理念、目標","an aim or idea that people support","a good cause","a cause you care about 你在乎的理念。"),
   w("organization","noun","/ˌɔːr.ɡən.əˈzeɪ.ʃən/","組織","a group of people working together for a purpose","a charity organization","an organization you trust 你信任的組織。")],
  [gr("without being + p.p.","沒有被…（被動動名詞）。","Volunteers give their time to help others without being paid."),
   gr("While 表讓步","雖然…（不是表時間）。","While the main goal is to help the community, research suggests volunteers benefit as well."),
   gr("it helps to + V","…會有幫助。","it helps to choose a cause you care about and an organization you trust")],
  [q("What do volunteers receive for their work?","No pay","A high salary","Free holidays"),
   q("What is the 'helper's high'?","A warm, happy feeling from helping","A tall building","A type of job"),
   q("What does the text suggest about volunteering time?","Regular small amounts can matter a lot","Only big efforts matter","Once a year is best")]),
 L("Do Schools Kill Creativity?", "學校扼殺了創造力嗎？", [
   "Sir Ken Robinson's talk is one of the most watched in TED history. Mixing humor with serious ideas, he argues that creativity is as important in education as reading and writing, and that it should be treated with the same respect.",
   "He points out that young children are not afraid of being wrong, so they try new things freely. As they grow up, schools often teach them that mistakes are bad, and many lose this confidence. He also notes that most school systems place math and languages at the top and the arts at the bottom.",
   "To illustrate his point, he tells the story of a girl who could not sit still in class. Instead of treating her as a problem, a specialist realized she was a natural dancer. She went on to become a famous choreographer, which shows how much talent schools can miss."],
  [w("humor","noun","/ˈhjuː.mɚ/","幽默","the quality of being funny","a sense of humor","Mixing humor with… 把幽默和…混合。"),
   w("creativity","noun","/ˌkriː.eɪˈtɪv.ə.t̬i/","創造力","the ability to make new and original things","Art encourages creativity.","不可數名詞。"),
   w("respect","noun","/rɪˈspekt/","尊重","a feeling that something is important","treat with respect","with the same respect 同樣尊重。"),
   w("mistake","noun","/mɪˈsteɪk/","錯誤","something that is wrong","make a mistake","mistakes are bad 錯誤是壞事。"),
   w("illustrate","verb","/ˈɪl.ə.streɪt/","說明、舉例","to explain by using examples","illustrate a point","To illustrate his point 為了說明他的觀點。"),
   w("specialist","noun","/ˈspeʃ.əl.ɪst/","專家","a person who knows a lot about one subject","a heart specialist","a specialist realized… 一位專家發現…。"),
   w("talent","noun","/ˈtæl.ənt/","天分","a natural ability to do something well","She has a talent for music.","how much talent 多少天分。")],
  [gr("as… as…","和…一樣…。","creativity is as important in education as reading and writing"),
   gr("be afraid of + V-ing","害怕…。","young children are not afraid of being wrong"),
   gr("go on to + V","接著（後來）去做…。","She went on to become a famous choreographer")],
  [q("What is Robinson's main argument?","Creativity is as important as literacy in education","Math should be removed from schools","Children should not go to school"),
   q("What happens to many children as they grow up, according to him?","They become afraid of mistakes","They become more creative","They stop reading"),
   q("What does the story of the dancer show?","Schools can miss real talent","Dancing is easy","Specialists are always wrong")]),
]

C1 = [
 L("The Many Lives of a Single Leaf", "一片茶葉的多種面貌", [
   "Tea is second only to water as the world's most widely consumed beverage, and its origins are wrapped in myth. Chinese tradition credits the legendary emperor Shennong, who is said to have discovered it when stray leaves drifted into his boiling water.",
   "Whatever the truth of that tale, the botanical reality is more surprising: green, black, white and oolong teas all derive from a single species, Camellia sinensis. What distinguishes them is processing, and in particular the degree of oxidation.",
   "Green tea is heated soon after picking to arrest that reaction, preserving its fresh, grassy character; black tea is allowed to oxidize fully, deepening into malty, robust flavors. Oolong occupies the intriguing territory in between, and its makers are celebrated for their skill in controlling the process precisely.",
   "Taiwan has carved out an outsized reputation in that territory. High-mountain oolongs from areas such as Alishan, where cool mists slow the leaves' growth, command premium prices. Meanwhile the island's more playful invention, bubble tea, has turned a local café experiment of the 1980s into a global phenomenon."],
  [w("beverage","noun","/ˈbev.ɚ.ɪdʒ/","飲料","a drink, especially not water","hot beverages","正式用字，= drink。"),
   w("credit","verb","/ˈkred.ɪt/","歸功於","to say that someone did something","He is credited with the idea.","credit A (with B) 把功勞歸給 A。"),
   w("derive","verb","/dɪˈraɪv/","源自","to come from something","The word derives from Latin.","derive from… 源於…。"),
   w("distinguish","verb","/dɪˈstɪŋ.ɡwɪʃ/","區分","to show the difference between things","What distinguishes them?","What distinguishes them is… 區分它們的是…。"),
   w("arrest","verb","/əˈrest/","阻止、使停止","to stop a process","arrest the decline","arrest that reaction 終止氧化反應。"),
   w("robust","adjective","/roʊˈbʌst/","濃郁的、強健的","strong in flavor or structure","a robust red wine","robust flavors 濃厚的風味。"),
   w("intriguing","adjective","/ɪnˈtriː.ɡɪŋ/","引人入勝的","very interesting because unusual","an intriguing question","intriguing territory 有趣的領域。"),
   w("outsized","adjective","/ˈaʊt.saɪzd/","超乎尋常的","larger than usual","an outsized influence","an outsized reputation 與規模不成比例的名聲。")],
  [gr("second only to","僅次於…。","Tea is second only to water as the world's most widely consumed beverage"),
   gr("is said to have + p.p.","據說曾經…。","who is said to have discovered it when stray leaves drifted into his boiling water"),
   gr("Whatever the truth of…","不管…的真相如何。","Whatever the truth of that tale, the botanical reality is more surprising")],
  [q("What mainly distinguishes different types of tea?","How the leaves are processed, especially oxidation","They come from different plants","The color of the cup"),
   q("Why is green tea heated soon after picking?","To stop oxidation","To make it black","To add sugar"),
   q("Why do Alishan oolongs command high prices?","Cool mountain conditions produce special leaves","They are fully oxidized","They contain bubbles")]),
 L("The Real Climate Math of Electric Cars", "電動車的真實碳排算術", [
   "Electric vehicles have moved from novelty to mainstream with remarkable speed, now accounting for a sizable share of new car sales worldwide. Their most obvious advantage is local: with no tailpipe, they eliminate exhaust emissions on the street, improving urban air quality and reducing noise.",
   "Their climate credentials, however, depend heavily on context. An electric car's lifetime footprint hinges on the carbon intensity of the grid that charges it, and manufacturing its battery is energy-intensive, so an EV typically starts life with a larger carbon debt than a comparable petrol car.",
   "Lifecycle analyses nonetheless find that this debt is usually repaid within a few years of driving, after which the electric car pulls steadily ahead. As grids add more renewable power, the margin widens further.",
   "Challenges remain. Mining lithium, cobalt and nickel raises environmental and human-rights concerns, prompting interest in recycling and alternative chemistries. And range anxiety, the fear of running out of charge, still deters some buyers, even as longer-range batteries and denser charging networks steadily erode its basis."],
  [w("novelty","noun","/ˈnɑː.vəl.t̬i/","新奇事物","something new and unusual","The novelty wore off.","from novelty to mainstream 從新奇到主流。"),
   w("mainstream","noun","/ˈmeɪn.striːm/","主流","the ideas or things most people accept","enter the mainstream","to mainstream 成為主流。"),
   w("credentials","noun","/krəˈden.ʃəlz/","資格、條件","qualities that make something suitable","green credentials","climate credentials 環保資格。"),
   w("hinges on","phrasal verb (hinge on)","/hɪndʒ ɑːn/","取決於","to depend completely on","Everything hinges on the vote.","hinges on 第三人稱單數。"),
   w("intensity","noun","/ɪnˈten.sə.t̬i/","強度","the level or strength of something","carbon intensity","carbon intensity 碳排強度。"),
   w("margin","noun","/ˈmɑːr.dʒɪn/","差距","the amount by which one thing is bigger than another","win by a wide margin","the margin widens 差距擴大。"),
   w("deter","verb","/dɪˈtɝː/","使打消念頭","to make someone not want to do something","High prices deter buyers.","deters 第三人稱單數。"),
   w("erode","verb","/ɪˈroʊd/","削弱","to gradually reduce","erode confidence","erode its basis 削弱它的根據。")],
  [gr("hinge on","完全取決於…。","An electric car's lifetime footprint hinges on the carbon intensity of the grid that charges it"),
   gr("after which","在那之後（關係子句）。","after which the electric car pulls steadily ahead"),
   gr("分詞構句 prompting…","表示結果：因此引發…。","prompting interest in recycling and alternative chemistries")],
  [q("Why do EVs start life with a 'carbon debt'?","Battery manufacturing uses a lot of energy","They burn petrol at first","They are imported"),
   q("What happens as grids add more renewable power?","EVs' climate advantage grows","EVs become dirtier","Petrol cars become cleaner"),
   q("What is range anxiety?","Fear of running out of charge","Fear of high prices","Fear of driving fast")]),
 L("The Two-Way Gift of Volunteering", "志願服務的雙向禮物", [
   "Volunteering is usually framed as a one-way transaction: people donate their time, and someone else benefits. Whether tutoring children, restoring coastlines or assisting after a disaster, volunteers fill gaps that neither markets nor governments always reach.",
   "A growing body of research suggests the exchange is more reciprocal than it appears. Regular volunteers tend to report greater life satisfaction, lower levels of loneliness and a stronger sense of purpose. Some describe a burst of well-being dubbed the 'helper's high'.",
   "Studies of older adults have even linked volunteering with better physical health, although it is difficult to disentangle cause from effect, since healthier people may simply be more able to volunteer.",
   "Good intentions are not sufficient on their own, however. Well-meaning efforts can backfire when volunteers lack relevant skills or arrive without understanding local needs, a criticism often leveled at short-term 'voluntourism' abroad. The most effective volunteers tend to commit consistently to a cause they care about, through organizations accountable to the communities they serve."],
  [w("transaction","noun","/trænˈzæk.ʃən/","交易","an exchange of something between people","a business transaction","a one-way transaction 單向交易。"),
   w("reciprocal","adjective","/rɪˈsɪp.rə.kəl/","互惠的","given and received by both sides","a reciprocal agreement","more reciprocal 更互惠。"),
   w("dub","verb","/dʌb/","稱為","to give someone or something a name","He was dubbed 'the King'.","dubbed 被稱作。"),
   w("disentangle","verb","/ˌdɪs.ɪnˈtæŋ.ɡəl/","釐清、區分","to separate things that are connected","disentangle fact from fiction","disentangle A from B 把 A 和 B 分開。"),
   w("intention","noun","/ɪnˈten.ʃən/","意圖","something you plan or want to do","good intentions","Good intentions 好意。"),
   w("backfire","verb","/ˈbæk.faɪr/","適得其反","to have the opposite result to what was intended","The plan backfired.","efforts can backfire 努力可能反效果。"),
   w("level","verb","/ˈlev.əl/","提出（批評、指控）","to direct criticism at someone","Criticism was leveled at the plan.","be leveled at… 被針對…。"),
   w("accountable","adjective","/əˈkaʊn.t̬ə.bəl/","負責的","responsible and required to explain actions","accountable to voters","accountable to… 對…負責。")],
  [gr("neither… nor…","既不…也不…。","volunteers fill gaps that neither markets nor governments always reach"),
   gr("since 表原因","since = because。","since healthier people may simply be more able to volunteer"),
   gr("過去分詞片語修飾名詞","accountable to… 修飾 organizations。","through organizations accountable to the communities they serve")],
  [q("How does the writer challenge the usual view of volunteering?","Volunteers also benefit, so it is reciprocal","Volunteers should be paid","Volunteering harms communities"),
   q("Why is the link between volunteering and health hard to prove?","Healthy people may simply volunteer more","There is no research","Older adults never volunteer"),
   q("What criticism is made of some 'voluntourism'?","Volunteers may lack skills or local understanding","It is too long","It is only for children")]),
 L("Do Schools Kill Creativity? Revisited", "重探〈學校扼殺創造力嗎？〉", [
   "Delivered in 2006, Sir Ken Robinson's talk remains one of the most viewed in TED's history, a testament both to his wit and to how deeply his argument struck a nerve. His central claim is deceptively simple: creativity deserves the same status in education as literacy.",
   "Robinson observes that young children will readily take a chance, unafraid of being wrong. By adulthood, many have lost that capacity, partly because schools treat mistakes as failures to be avoided.",
   "He traces this to the industrial origins of mass schooling. The systems he describes rank subjects in a rigid hierarchy, with mathematics and languages at the top, the humanities in the middle and the arts at the bottom, reflecting what economies once needed rather than the full range of human ability.",
   "His most memorable illustration is the story of a girl whose restlessness at school was mistaken for a learning problem. A perceptive specialist recognized her as a dancer instead, and she went on to an illustrious career in choreography. The anecdote crystallizes his warning that rigid systems risk squandering the very talents they ought to nurture."],
  [w("testament","noun","/ˈtes.tə.mənt/","證明","something that shows that something else is true","a testament to his skill","a testament to… …的明證。"),
   w("struck a nerve","idiom (strike a nerve)","/straɪk ə nɝːv/","觸動人心","to upset or affect people strongly","Her comments struck a nerve.","struck 為 strike 的過去式／過去分詞。"),
   w("deceptively","adverb","/dɪˈsep.tɪv.li/","看似…實則不然","in a way that seems different from the reality","deceptively simple","deceptively simple 看似簡單。"),
   w("readily","adverb","/ˈred.əl.i/","樂意地、輕易地","quickly and willingly","She readily agreed.","readily take a chance 願意冒險。"),
   w("hierarchy","noun","/ˈhaɪ.rɑːr.ki/","階層","a system in which things are ranked","a rigid hierarchy","a hierarchy of subjects 科目階級。"),
   w("perceptive","adjective","/pɚˈsep.tɪv/","有洞察力的","quick to notice and understand things","a perceptive teacher","a perceptive specialist 有洞察力的專家。"),
   w("illustrious","adjective","/ɪˈlʌs.tri.əs/","傑出的、輝煌的","famous and admired","an illustrious career","illustrious career 輝煌生涯。"),
   w("squander","verb","/ˈskwɑːn.dɚ/","浪費","to waste something valuable","squander money","risk squandering 有浪費…的風險。")],
  [gr("a testament both to A and to B","同時證明 A 和 B。","a testament both to his wit and to how deeply his argument struck a nerve"),
   gr("trace A to B","把 A 的起源追溯到 B。","He traces this to the industrial origins of mass schooling."),
   gr("the very + 名詞","正是那些…（強調）。","rigid systems risk squandering the very talents they ought to nurture")],
  [q("What is Robinson's central claim?","Creativity deserves equal status with literacy","Schools should close","Math is unimportant"),
   q("Where does he trace the subject hierarchy to?","The industrial origins of mass schooling","Ancient Greece","Modern technology"),
   q("What does the dancer's story illustrate?","Rigid systems can waste talent","All restless children are dancers","Specialists are usually wrong")]),
]
